 ## Languages

 Messages exist in English (`en`) and Korean (`ko`), in
-`src/i18n/messages.js`. The server answers in `LARDER_LANG` (default `en`).
+`src/i18n/messages.js`. The server selects `en` or `ko` from the
+`Accept-Language` header, honoring quality values and region tags. Equal
+quality values follow header order. If no supported language has a positive
+quality value, it uses `LARDER_LANG` (default `en`).
diff --git a/src/http/server.js b/src/http/server.js
index 94dd739..7a98b6a 100644
--- a/src/http/server.js
+++ b/src/http/server.js
@@ -15,11 +15,33 @@ import { kitchenRoutes } from "./routes/kitchen.js";

 const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes]);

+function requestLanguage(headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  if (typeof header !== "string") return config.defaultLanguage;
+  let best = null;
+  let bestQuality = 0;
+  for (const entry of header.split(",")) {
+    const [range, ...parameters] = entry.trim().split(";");
+    const language = range.trim().toLowerCase();
+    if (!/^(en|ko)(-[a-z0-9]{1,8})*$/.test(language)) continue;
+    let quality = 1;
+    if (parameters.length) {
+      if (parameters.length !== 1 || !/^\s*q\s*=\s*(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)\s*$/i.test(parameters[0])) continue;
+      quality = Number(parameters[0].split("=")[1]);
+    }
+    if (quality > bestQuality) {
+      best = language.split("-")[0];
+      bestQuality = quality;
+    }
+  }
+  return best ?? config.defaultLanguage;
+}
+
 /** Builds the request handler over a store. `clock` returns now (ms). */
 export function createApp(store, { clock = () => Date.now() } = {}) {
   return async function handle({ method = "GET", path, headers = {}, body = null }) {
     const url = new URL(path, "http://larder");
-    const lang = config.defaultLanguage;
+    const lang = requestLanguage(headers);
     try {
       const found = match(method, url.pathname);
       if (!found) throw new AppError("not_found");
@@ -34,7 +56,7 @@ export function createApp(store, { clock = () => Date.now() } = {}) {
     } catch (e) {
       if (e instanceof AppError) return { status: e.status, body: errorBody(e.code, t(e.code, lang, e.params)) };
       log.error("unhandled", { message: e.message });
-      return { status: 500, body: errorBody("internal", "Something went wrong.") };
+      return { status: 500, body: errorBody("internal", t("internal", lang)) };
     }
   };
 }
